-- Enriches the TPC-C data generated by BenchBase so that it behaves like an e-commerce shop.
-- Run as DWH_OLTP after the BenchBase load (and after the workload run). The script can be repeated safely.
--
--   * products get a category and a brand
--   * warehouses get a Turkish city and region, customers inherit the region
--   * orders are spread over almost three years and get a payment method
--   * order lines and payments get dates that follow the order date
--   * some customers order far more often than others (needed for RFM analysis)

SET SERVEROUTPUT ON;
WHENEVER SQLERROR EXIT FAILURE ROLLBACK;

-- Columns are added only when they are missing so the script can run twice.
DECLARE
    PROCEDURE add_column(p_table VARCHAR2, p_column VARCHAR2, p_definition VARCHAR2) IS
        v_count NUMBER;
    BEGIN
        SELECT COUNT(*) INTO v_count FROM user_tab_columns
         WHERE table_name = p_table AND column_name = p_column;
        IF v_count = 0 THEN
            EXECUTE IMMEDIATE 'ALTER TABLE ' || p_table || ' ADD (' || p_column || ' ' || p_definition || ')';
        END IF;
    END;
BEGIN
    add_column('ITEM', 'I_CATEGORY', 'VARCHAR2(30)');
    add_column('ITEM', 'I_BRAND', 'VARCHAR2(30)');
    add_column('WAREHOUSE', 'W_REGION', 'VARCHAR2(30)');
    add_column('CUSTOMER', 'C_REGION', 'VARCHAR2(30)');
    add_column('CUSTOMER', 'C_EMAIL', 'VARCHAR2(60)');
    add_column('OORDER', 'O_PAYMENT_METHOD', 'VARCHAR2(20)');
END;
/

-- Products ---------------------------------------------------------------------------------------
UPDATE item SET
    i_category = CASE MOD(i_id, 8)
        WHEN 0 THEN 'Electronics'
        WHEN 1 THEN 'Clothing'
        WHEN 2 THEN 'Home and Kitchen'
        WHEN 3 THEN 'Books'
        WHEN 4 THEN 'Sports and Outdoor'
        WHEN 5 THEN 'Beauty and Care'
        WHEN 6 THEN 'Toys and Games'
        ELSE 'Grocery'
    END,
    i_brand = 'Brand ' || CHR(65 + MOD(ORA_HASH(i_id, 24), 12));

-- Warehouses and customers -----------------------------------------------------------------------
UPDATE warehouse SET
    w_city = CASE MOD(w_id, 10)
        WHEN 0 THEN 'Istanbul'
        WHEN 1 THEN 'Ankara'
        WHEN 2 THEN 'Izmir'
        WHEN 3 THEN 'Bursa'
        WHEN 4 THEN 'Antalya'
        WHEN 5 THEN 'Adana'
        WHEN 6 THEN 'Konya'
        WHEN 7 THEN 'Gaziantep'
        WHEN 8 THEN 'Trabzon'
        ELSE 'Eskisehir'
    END,
    w_region = CASE MOD(w_id, 10)
        WHEN 0 THEN 'Marmara'
        WHEN 1 THEN 'Central Anatolia'
        WHEN 2 THEN 'Aegean'
        WHEN 3 THEN 'Marmara'
        WHEN 4 THEN 'Mediterranean'
        WHEN 5 THEN 'Mediterranean'
        WHEN 6 THEN 'Central Anatolia'
        WHEN 7 THEN 'Southeastern Anatolia'
        WHEN 8 THEN 'Black Sea'
        ELSE 'Central Anatolia'
    END;

-- Most customers live in the region of their warehouse, the rest are spread over the other regions.
UPDATE customer c SET
    c_region = CASE
        WHEN MOD(ORA_HASH(c.c_w_id || '-' || c.c_d_id || '-' || c.c_id, 9), 10) < 7
            THEN (SELECT w.w_region FROM warehouse w WHERE w.w_id = c.c_w_id)
        ELSE CASE MOD(ORA_HASH(c.c_id || '-' || c.c_d_id, 6), 7)
            WHEN 0 THEN 'Marmara'
            WHEN 1 THEN 'Aegean'
            WHEN 2 THEN 'Mediterranean'
            WHEN 3 THEN 'Central Anatolia'
            WHEN 4 THEN 'Black Sea'
            WHEN 5 THEN 'Eastern Anatolia'
            ELSE 'Southeastern Anatolia'
        END
    END,
    c_email = LOWER(TRIM(c.c_first)) || '.' || LOWER(TRIM(c.c_last)) || '.' || c.c_w_id || c.c_d_id || c.c_id || '@mail.example';

-- Orders -----------------------------------------------------------------------------------------
-- Every district gets its own order sequence; the date grows with the order number so that older
-- orders really are older. The jitter keeps the orders of one day from looking identical.
MERGE INTO oorder o
USING (
    SELECT o_w_id, o_d_id, o_id,
           o_id / MAX(o_id) OVER (PARTITION BY o_w_id, o_d_id) AS progress
      FROM oorder
) s
ON (o.o_w_id = s.o_w_id AND o.o_d_id = s.o_d_id AND o.o_id = s.o_id)
WHEN MATCHED THEN UPDATE SET
    o.o_entry_d = DATE '2024-01-01'
                  + FLOOR(s.progress * 1035)
                  + ORA_HASH(s.o_w_id || '-' || s.o_d_id || '-' || s.o_id, 86399) / 86400,
    o.o_payment_method = CASE MOD(ORA_HASH(s.o_w_id || ':' || s.o_d_id || ':' || s.o_id, 99), 10)
        WHEN 0 THEN 'WALLET'
        WHEN 1 THEN 'BANK_TRANSFER'
        WHEN 2 THEN 'CASH_ON_DELIVERY'
        WHEN 3 THEN 'CASH_ON_DELIVERY'
        ELSE 'CREDIT_CARD'
    END;

-- Repeat customers: the customer of an order is drawn from a skewed distribution so that a small
-- group of customers places many orders while most customers place only a few.
UPDATE oorder SET
    o_c_id = 1 + FLOOR(3000 * POWER(ORA_HASH(o_w_id || '/' || o_d_id || '/' || o_id, 999999) / 1000000, 2.5));

-- Order lines follow their order: delivered orders are delivered one to seven days after purchase.
UPDATE order_line ol SET ol_delivery_d = (
    SELECT o.o_entry_d + 1 + MOD(ORA_HASH(ol.ol_w_id || '-' || ol.ol_d_id || '-' || ol.ol_o_id, 6), 7)
      FROM oorder o
     WHERE o.o_w_id = ol.ol_w_id AND o.o_d_id = ol.ol_d_id AND o.o_id = ol.ol_o_id
       AND o.o_carrier_id IS NOT NULL
);

-- Customers register before their first order and payments are booked on the order date.
UPDATE customer c SET c_since = NVL(
    (SELECT MIN(o.o_entry_d) - MOD(ORA_HASH(c.c_w_id || '-' || c.c_d_id || '-' || c.c_id, 90), 91)
       FROM oorder o
      WHERE o.o_w_id = c.c_w_id AND o.o_d_id = c.c_d_id AND o.o_c_id = c.c_id),
    c.c_since);

UPDATE history h SET h_date = NVL(
    (SELECT MAX(o.o_entry_d)
       FROM oorder o
      WHERE o.o_w_id = h.h_c_w_id AND o.o_d_id = h.h_c_d_id AND o.o_c_id = h.h_c_id),
    h.h_date);

COMMIT;

-- Indexes used by the ETL when it reads the OLTP schema ---------------------------------------
DECLARE
    PROCEDURE create_index(p_name VARCHAR2, p_ddl VARCHAR2) IS
        v_count NUMBER;
    BEGIN
        SELECT COUNT(*) INTO v_count FROM user_indexes WHERE index_name = p_name;
        IF v_count = 0 THEN
            EXECUTE IMMEDIATE p_ddl;
        END IF;
    END;
BEGIN
    create_index('IDX_OORDER_ENTRY_D', 'CREATE INDEX idx_oorder_entry_d ON oorder (o_entry_d)');
    create_index('IDX_OORDER_CUSTOMER', 'CREATE INDEX idx_oorder_customer ON oorder (o_w_id, o_d_id, o_c_id)');
END;
/

-- Sequences for the ids that the shop service creates itself (TPC-C has none) -------------------
DECLARE
    PROCEDURE create_sequence(p_name VARCHAR2, p_table VARCHAR2, p_column VARCHAR2) IS
        v_count NUMBER;
        v_start NUMBER;
    BEGIN
        SELECT COUNT(*) INTO v_count FROM user_sequences WHERE sequence_name = p_name;
        IF v_count = 0 THEN
            EXECUTE IMMEDIATE 'SELECT NVL(MAX(' || p_column || '), 0) + 1 FROM ' || p_table INTO v_start;
            EXECUTE IMMEDIATE 'CREATE SEQUENCE ' || p_name || ' START WITH ' || v_start || ' NOCACHE';
        END IF;
    END;
BEGIN
    create_sequence('SEQ_ITEM_ID', 'ITEM', 'I_ID');
    create_sequence('SEQ_WAREHOUSE_ID', 'WAREHOUSE', 'W_ID');
END;
/

EXIT;
